import functools
import inspect
from typing import ForwardRef, get_type_hints
from fastapi.dependencies.utils import get_typed_signature, get_typed_return_annotation

# Define a type in this module
class MyType:
    pass

def original_func(a: "MyType") -> "MyType":
    return a

@functools.wraps(original_func)
def wrapper_func(a: "MyType") -> "MyType":
    return original_func(a)

def test_get_typed_signature():
    print("Testing get_typed_signature...")
    try:
        sig = get_typed_signature(wrapper_func)
        print("Success!")
        for param in sig.parameters.values():
            print(f"Param {param.name}: {param.annotation}")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

def test_get_typed_return_annotation():
    print("\nTesting get_typed_return_annotation...")
    try:
        ann = get_typed_return_annotation(wrapper_func)
        print("Success!")
        print(f"Return annotation: {ann}")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_get_typed_signature()
    test_get_typed_return_annotation()

